function initializeMentorTransfers(){if(!users.some(u=>u.id==='m2'))users.push({id:'m2',name:'Dr. Nisha Shrestha',role:'Alternate Mentor / Verifier'});db.mentorTransfers??=[]}
function mentorTransferPending(r){return ['REQUESTED','HANDOVER_SUBMITTED','ACKNOWLEDGED'].includes(r.state)}
function mentorTransferById(id){return (db.mentorTransfers||[]).find(r=>r.id===id)}
function mentorTransferVisible(r,actor=uid){let p=db.projects.find(p=>p.id===r.projectId);return [r.from,r.to,r.requestedBy,'c1','d1','a1'].includes(actor)||!!p&&(p.members.includes(actor)||actor==='sa1')}
function mentorTransferPrivate(r,actor=uid){return [r.from,r.to,r.requestedBy,'c1','d1','a1'].includes(actor)}
function mentorTransferOpen(p){return !!p&&p.activityControl?.state!=='CANCELLED'&&!['CLOSED','ARCHIVED'].includes(p.state)}
function mentorTransferBasis(p){return JSON.stringify({mentor:p.mentor,due:p.due,activityControl:p.activityControl,deliveryScheduleAmendment:p.deliveryScheduleAmendment,assignmentVersion:p.mentorAssignmentVersion||1,owner:p.owner,state:p.state,developmentPlans:(p.developmentPlans||[]).map(r=>({id:r.id,version:r.version,state:r.state,reviews:r.reviews.length,followUp:r.followUp})),tasks:p.tasks.map(t=>({id:t.id,assignee:t.assignee,done:t.done,mappingVersion:t.mappingVersion,workState:t.workState,submissionVersion:(t.submissions||[]).at(-1)?.version,reviewVersion:(t.taskReviews||[]).at(-1)?.version})),evidence:p.evidence.map(e=>({by:e.by,verified:e.verified,files:(e.files||[]).map(f=>f.id)})),reflections:Object.entries(p.reflections).map(([student,r])=>({student,version:r.version||1})),evaluations:Object.entries(p.evaluations).map(([student,e])=>({student,version:e.version||1,final:e.final})),deliveryPlan:p.deliveryPlan?{version:p.deliveryPlan.version,state:p.deliveryPlan.state}:null,deliveryRun:p.deliveryRun,deliverySubmissions:(p.deliverySubmissions||[]).map(s=>({student:s.student,kind:s.kind,version:s.version,state:s.state})),sessions:(p.sessions||[]).map(s=>({id:s.id,version:s.version,state:s.state})),contributions:(p.contributions||[]).map(s=>({id:s.id,version:s.version,state:s.state})),appeals:(p.evaluationAppeals||[]).map(a=>({id:a.id,state:a.state})),outcomes:(p.outcomeRequests||[]).map(a=>({id:a.id,state:a.state}))})}
function mentorHandoverCurrent(r){let p=db.projects.find(p=>p.id===r.projectId);return !!p&&r.handoverBasis===mentorTransferBasis(p)}
function mentorTransferCurrent(r){let p=db.projects.find(p=>p.id===r.projectId);return mentorTransferOpen(p)&&p.mentor===r.from&&(p.mentorAssignmentVersion||1)===r.assignmentVersion}
function mentorHandoverSummary(p){return {state:p.state,programme:p.programme,due:p.due,participants:p.members.length,unfinishedTasks:p.tasks.filter(t=>!t.done).length,evidenceAwaitingVerification:p.evidence.filter(e=>!e.verified).length,reflectionsSubmitted:Object.keys(p.reflections).length,finalEvaluations:Object.values(p.evaluations).filter(e=>e.final).length,pendingAppeals:(p.evaluationAppeals||[]).filter(a=>!['REJECTED','REVERIFIED'].includes(a.state)).length}}
function mentorAssignmentPage(){initializeMentorTransfers();let projects=visible().filter(p=>mentorTransferOpen(p)&&(mentor(p)||uid==='c1'));return heading('Mentor assignments & handover','Effective-dated activity-level reassignment with independent approval.')+`<div class="notice">Demonstration sequence: current mentor or Programme Coordinator requests → outgoing mentor submits handover → incoming mentor acknowledges → Department Head approves. The assignment changes immediately at approval, with no backdating. Past evaluations, approvals and certificate issuer snapshots are retained. Club mentors, source academic plans and finance authorities are separate assignments.</div>${projects.length?`<div class="panel"><h2>Request a reassignment</h2>${projects.map(p=>`<div class="row"><span>${esc(p.title)} · Current mentor ${esc(name(p.mentor))}</span>${!(db.mentorTransfers||[]).some(r=>r.projectId===p.id&&mentorTransferPending(r))?btn('Request transfer',`mentorTransferForm('${p.id}')`):'<span class="meta">Transfer already pending</span>'}</div>`).join('')}</div>`:''}${(db.mentorTransfers||[]).filter(r=>mentorTransferVisible(r)).slice().reverse().map(r=>{let full=mentorTransferPrivate(r),current=r.handoverCurrent??mentorHandoverCurrent(r);return `<div class="panel" style="margin:18px 0"><div class="top"><h2>${esc(r.title)}</h2>${pill(r.state)}</div><p>${esc(name(r.from))} → ${esc(name(r.to))}</p><p class="meta">Requested ${esc(eventTime(r.requestedAt))}${r.effectiveAt?' · Effective '+esc(eventTime(r.effectiveAt)):''}</p>${full?`<p>Reason: ${esc(r.reason)}</p>${r.summary?`<p>Handover snapshot: ${esc(label(r.summary.state))} · ${r.summary.participants} participants · ${r.summary.unfinishedTasks} unfinished tasks · ${r.summary.evidenceAwaitingVerification} evidence items awaiting verification · ${r.summary.finalEvaluations} final evaluations · ${r.summary.pendingAppeals} pending appeals.</p><p>Outstanding responsibilities: ${esc(r.handover?.responsibilities)}</p><p>Evidence / records references: ${esc(r.handover?.references)}</p><p>Risks and next steps: ${esc(r.handover?.nextSteps)}</p>`:''}${mentorTransferPending(r)&&r.handover&&!current?'<div class="notice">The activity changed after this handover snapshot. The outgoing mentor must refresh it and the incoming mentor must acknowledge the new version.</div>':''}${r.decisionReason?`<p>Decision: ${esc(r.decisionReason)} · ${esc(name(r.decidedBy))} · ${esc(eventTime(r.decidedAt))}</p>`:''}<div class="buttons">${uid===r.from&&mentorTransferPending(r)?btn(r.handover?'Refresh outgoing handover':'Submit outgoing handover',`mentorHandoverForm('${r.id}')`):''}${uid===r.to&&r.state==='HANDOVER_SUBMITTED'?btn('Acknowledge handover',`ackMentorHandover('${r.id}')`):''}${uid===r.to&&mentorTransferPending(r)?btn('Decline assignment',`mentorTransferDecisionForm('${r.id}','DECLINED')`):''}${uid==='d1'&&r.state==='ACKNOWLEDGED'?btn('Approve effective reassignment',`mentorTransferDecisionForm('${r.id}','APPROVED')`,'primary'):''}${uid==='d1'&&mentorTransferPending(r)?btn('Reject request',`mentorTransferDecisionForm('${r.id}','REJECTED')`):''}${[r.requestedBy,r.from,'c1'].includes(uid)&&mentorTransferPending(r)?btn('Cancel request',`mentorTransferDecisionForm('${r.id}','CANCELLED')`):''}</div><details><summary>Transfer event history</summary>${r.events.map(e=>`<p>${esc(e.state)} · ${esc(name(e.by))} · ${esc(eventTime(e.time))}${e.reason?' · '+esc(e.reason):''}</p>`).join('')}</details>`:'<p>Operational handover notes are restricted to the involved mentors and designated reviewers.</p>'}</div>`}).join('')||'<div class="panel">No mentor transfer records are visible to this account.</div>'}`}
function mentorTransferForm(pid){let p=db.projects.find(p=>p.id===pid);if(!mentorTransferOpen(p)||!(mentor(p)||uid==='c1'))return;let choices=users.filter(u=>['m1','m2'].includes(u.id)&&u.id!==p.mentor&&!p.members.includes(u.id));modal(`<h2>Request activity mentor reassignment</h2><p>${esc(p.title)} · Current mentor ${esc(name(p.mentor))}</p><form onsubmit="requestMentorTransfer(event,'${pid}')"><label>Proposed mentor<select name="to">${choices.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><label>Operational reason<textarea name="reason" required></textarea></label><p>The existing mentor retains authority until independent approval. Do not paste confidential grades, personal circumstances or credentials in handover notes.</p><button class="primary">Request transfer</button></form>`)}
function mentorTransferEvent(r,state,reason){r.state=state;r.events.push({state,reason,by:uid,time:new Date().toISOString()});let p=db.projects.find(p=>p.id===r.projectId);log(p,'Mentor transfer '+state+' / '+r.id);closeModal();render()}
function requestMentorTransfer(e,pid){e.preventDefault();let p=db.projects.find(p=>p.id===pid),f=new FormData(e.target),to=f.get('to'),reason=f.get('reason').trim();if(!mentorTransferOpen(p)||!(mentor(p)||uid==='c1')||!['m1','m2'].includes(to)||to===p.mentor||p.members.includes(to)||!reason)return toast('An authorized requester, eligible alternate mentor and reason are required.');if(db.mentorTransfers.some(r=>r.projectId===pid&&mentorTransferPending(r)))return toast('Resolve the existing pending transfer first.');let r={id:clubKey('MT'),projectId:pid,title:p.title,programme:p.programme,from:p.mentor,to,assignmentVersion:p.mentorAssignmentVersion||1,reason,requestedBy:uid,requestedAt:new Date().toISOString(),events:[]};db.mentorTransfers.push(r);mentorTransferEvent(r,'REQUESTED','Assignment review requested')}
function mentorHandoverForm(id){let r=mentorTransferById(id);if(!r||uid!==r.from||!mentorTransferPending(r))return;modal(`<h2>Outgoing mentor handover</h2><form onsubmit="submitMentorHandover(event,'${id}')">${[['responsibilities','Pending duties and decisions'],['references','Evidence / records references (no private content)'],['nextSteps','Risks, deadlines and next steps']].map(([n,l])=>`<label>${l}<textarea name="${n}" required>${esc(r.handover?.[n]||'')}</textarea></label>`).join('')}<p>The system binds this handover to the current work status. Refreshing it requires a new incoming acknowledgment.</p><button class="primary">Submit current handover snapshot</button></form>`)}
function submitMentorHandover(e,id){e.preventDefault();let r=mentorTransferById(id),f=Object.fromEntries(new FormData(e.target));if(!r||uid!==r.from||!mentorTransferPending(r)||!mentorTransferCurrent(r))return toast('The current outgoing mentor and an open assignment are required.');if(['responsibilities','references','nextSteps'].some(k=>!f[k]?.trim()))return toast('Complete the handover responsibilities, references and next steps.');let p=db.projects.find(p=>p.id===r.projectId);if(r.handover){r.handoverHistory??=[];r.handoverHistory.push({version:r.handoverVersion,handover:r.handover,summary:r.summary,submittedAt:r.handoverAt,acknowledgedAt:r.acknowledgedAt||null})}r.handover=f;r.handoverVersion=(r.handoverVersion||0)+1;r.handoverAt=new Date().toISOString();r.summary=mentorHandoverSummary(p);r.handoverBasis=mentorTransferBasis(p);delete r.acknowledgedAt;delete r.acknowledgedBy;delete r.acknowledgedVersion;mentorTransferEvent(r,'HANDOVER_SUBMITTED','Outgoing handover v'+r.handoverVersion+' submitted')}
function ackMentorHandover(id){let r=mentorTransferById(id);if(!r||uid!==r.to||r.state!=='HANDOVER_SUBMITTED'||!mentorTransferCurrent(r)||!mentorHandoverCurrent(r))return toast('A current handover snapshot and incoming mentor are required.');r.acknowledgedBy=uid;r.acknowledgedAt=new Date().toISOString();r.acknowledgedVersion=r.handoverVersion;mentorTransferEvent(r,'ACKNOWLEDGED','Incoming mentor acknowledged responsibilities')}
function mentorTransferDecisionForm(id,decision){modal(`<h2>${esc(label(decision))} mentor transfer</h2><form onsubmit="decideMentorTransfer(event,'${id}','${decision}')"><label>Decision reason<textarea name="reason" required></textarea></label><p>Approval changes the current mentor immediately. Earlier approvals and learning records retain their original actors.</p><button class="primary">Record decision</button></form>`)}
function decideMentorTransfer(e,id,decision){e.preventDefault();let r=mentorTransferById(id),reason=new FormData(e.target).get('reason').trim();if(!r||!mentorTransferPending(r)||!reason)return;let review=uid==='d1'&&![r.from,r.to,r.requestedBy].includes(uid)&&['APPROVED','REJECTED'].includes(decision),cancel=[r.requestedBy,r.from,'c1'].includes(uid)&&decision==='CANCELLED',decline=uid===r.to&&decision==='DECLINED';if(!review&&!cancel&&!decline)return toast('Independent review or an involved party decision is required.');if(decision==='APPROVED'){if(r.state!=='ACKNOWLEDGED'||!mentorTransferCurrent(r)||!mentorHandoverCurrent(r)||r.acknowledgedBy!==r.to||r.acknowledgedVersion!==r.handoverVersion)return toast('Refresh any stale handover and obtain the incoming acknowledgment before approval.');let p=db.projects.find(p=>p.id===r.projectId),now=new Date().toISOString();if(p.members.includes(r.to))return toast('A participant cannot become their own evaluator.');p.mentorHistory??=[];let prior=p.mentorHistory.findLast(h=>h.mentor===p.mentor&&h.validTo===null);if(prior)prior.validTo=now;else p.mentorHistory.push({mentor:p.mentor,version:p.mentorAssignmentVersion||1,validFrom:p.mentorAssignedAt||null,validTo:now,origin:p.mentorAssignedAt?'Previous recorded assignment':'Existing assignment; start date unavailable'});p.mentorAssignmentVersion=(p.mentorAssignmentVersion||1)+1;p.mentor=r.to;p.mentorAssignedAt=now;p.mentorHistory.push({mentor:r.to,version:p.mentorAssignmentVersion,validFrom:now,validTo:null,requestId:r.id,approvedBy:uid,origin:'Approved mentor reassignment'});r.effectiveAt=now}r.decidedBy=uid;r.decidedAt=new Date().toISOString();r.decisionReason=reason;mentorTransferEvent(r,decision,reason)}
function mentorAssignmentHistory(p){return `<details><summary>Mentor assignment history</summary>${(p.mentorHistory||[]).map(h=>`<p>${esc(name(h.mentor))} · v${h.version} · ${esc(h.validFrom||'Start date unavailable')} → ${esc(h.validTo||'Current')} · ${esc(h.origin)}</p>`).join('')||'<p>Current assignment: '+esc(name(p.mentor))+'. No prior effective-dated transfer is recorded.</p>'}</details>`}
function mentorTransferActionCards(){let rows=(db.mentorTransfers||[]).filter(r=>mentorTransferVisible(r)&&mentorTransferPending(r)&&((r.state==='REQUESTED'&&uid===r.from)||(r.state==='HANDOVER_SUBMITTED'&&uid===r.to)||(r.state==='ACKNOWLEDGED'&&uid==='d1')));return rows.length?`<div class="panel" style="margin-top:20px"><h2>Mentor handover actions</h2>${rows.map(r=>`<div class="row"><span>${esc(r.title)} · ${esc(label(r.state))}</span>${btn('Review transfer',"go('Mentor Assignments')")}</div>`).join('')}</div>`:''}
